import{_ as e,o as d,c as a,a2 as i}from"./chunks/framework.1lR7qgqY.js";const p=JSON.parse('{"title":"授權紅旗","description":"","frontmatter":{},"headers":[],"relativePath":"decide/license-flags.md","filePath":"decide/license-flags.md","lastUpdated":1793001931000}'),r={name:"decide/license-flags.md"};function l(o,t,n,s,c,h){return d(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="授權紅旗" tabindex="-1">授權紅旗 <a class="header-anchor" href="#授權紅旗" aria-label="Permalink to &quot;授權紅旗&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: 決策參考</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 授權條款會改版, 對外提供服務前請以各專案儲存庫的授權檔為準; 本頁不構成法律意見</li></ul></div><p><strong>結論</strong>: 個人與內部使用通常不受授權限制影響 (信心: 中). 一旦要對外提供服務, 或把多個元件組成產品, 就要先檢查下列紅旗. 各元件的授權明細見<a href="/docs-handbook-poc/ref/licenses">授權速查</a>.</p><table tabindex="0"><thead><tr><th>紅旗</th><th>說明</th><th>涉及的元件 (依授權速查)</th></tr></thead><tbody><tr><td>原始碼公開但非 OSI 開源</td><td>授權對使用方式設有限制, 不能當作一般開源元件處理</td><td>n8n, Dify, LobeHub, MinerU, Arize Phoenix, Open WebUI (品牌條款)</td></tr><tr><td>品牌或標示條款</td><td>限制修改或移除標示</td><td>Open WebUI, Dify</td></tr><tr><td>多租戶服務限制</td><td>未經書面授權不得營運多租戶服務</td><td>Dify</td></tr><tr><td>規模或營收門檻</td><td>超過門檻須另取商業授權</td><td>MinerU</td></tr><tr><td>衍生作品散布限制</td><td>散布修改後的衍生作品須商業授權</td><td>LobeHub</td></tr><tr><td>部分目錄或功能另有授權</td><td>同一專案內不同目錄授權不同</td><td>LiteLLM (<code>enterprise/</code> 目錄), LibreChat (管理面板為 AGPL), LangGraph (官方 Agent Server 在正式環境須授權金鑰)</td></tr><tr><td>模型授權</td><td>須申請下載, 或附使用條款</td><td>Llama 4 Community License, Gemma 條款</td></tr><tr><td>授權會改版</td><td>同一專案可能在新版改授權</td><td>Dify, MinerU, LobeHub 都曾改過</td></tr></tbody></table><h2 id="建議做法" tabindex="-1">建議做法 <a class="header-anchor" href="#建議做法" aria-label="Permalink to &quot;建議做法&quot;">​</a></h2><ol><li>對外提供服務前, 列出所有元件與模型的授權, 找出上表中有紅旗的元件.</li><li>有紅旗的元件時, 優先尋找授權較寬鬆的替代品, 其次才評估取得商業授權.</li><li>組合多個元件時, 最嚴格的條款決定能做什麼 (信心: 中).</li><li>記錄所用版本的授權原文與取得日期, 授權改版時才能比對.</li><li>有疑義時請洽法律顧問.</li></ol>',6)])])}const _=e(r,[["render",l]]);export{p as __pageData,_ as default};
